def isolate_pairs(x):
 if isinstance(x,list):
  if len(x)==2 and all(isinstance(v,str) for v in x) and re.search('[\u0600-\u06ff]',x[0]):
   def protect(m):
    v=m.group(0)
    if not re.search('[A-Za-z0-9]',v):return v
    return v[:len(v)-len(v.lstrip())]+'\u2066'+v.strip()+'\u2069'+v[len(v.rstrip()):]
   x[0]=re.sub(r'''[A-Za-z0-9_"'\[\]()=.,+<>{}@#$%&:/?!\- ]+''',protect,x[0])
  else:
   for v in x:isolate_pairs(v)
 elif isinstance(x,dict):
  for v in x.values():isolate_pairs(v)
